def minInsertions(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]
    for i in range(n - 2, -1, -1):
        row = dp[i]
        nxt = dp[i + 1]
        for j in range(i + 1, n):
            if s[i] == s[j]:
                row[j] = nxt[j - 1]
            else:
                a = nxt[j]
                b = row[j - 1]
                row[j] = 1 + (a if a < b else b)
    return dp[0][n - 1]
